window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1a3ff965e48e8b15"]={"versions": [{"id": "FIG-1a3ff965e48e8b15", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktogramm (Nassi-Shneiderman-Diagramm) zur Darstellung der Regelausführung innerhalb des AUTOSAR Basic Software Mode Managers (BswM). Das Diagramm visualisiert die interne Kontroll- und Entscheidungslogik im Teilbereich »Mode Arbitration« des BswM.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt den BswM als übergeordnete Komponente mit folgenden internen Entitäten und Elementen:</p>\n<ul class=\"fig-list\"><li><strong>Mode Arbitration</strong>: Bewertungseinheit für konfigurierte Regeln basierend auf einer logischen Bedingung (<code>condition == true</code>).\n</li><li><strong>Verzweigungsäste</strong>: Binäre Verzweigung nach Auswertungsergebnis (<code>yes</code> / <code>no</code>).\n</li><li><strong>True – Actionlist</strong>: Aktionsliste, die dem positiven Auswertungspfad (<code>yes</code>) zugeordnet ist.\n</li><li><strong>False – Actionlist</strong>: Aktionsliste, die dem negativen Auswertungspfad (<code>no</code>) zugeordnet ist.\n</li><li><strong>Aktionen</strong>: Inhalt beider Aktionslisten ist jeweils die Ausführung von API-Aufrufen oder weiteren Mode Arbitrations (»Execution of API calls or further mode arbitrations«). Direkte Schnittstellen nach außen sind nicht abgebildet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Mode Arbitration prüft eine konfigurierte logische Bedingung (<code>condition == true</code>).\n</li><li>Evaluiert die Bedingung zu <code>yes</code> (wahr), wird die <code>True – Actionlist</code> abgearbeitet.\n</li><li>Evaluiert die Bedingung zu <code>no</code> (falsch), wird die <code>False – Actionlist</code> abgearbeitet.\n</li><li>Bei Abarbeitung der jeweiligen Aktionsliste werden die hinterlegten API-Aufrufe abgesetzt oder nachfolgende Mode Arbitrations rekursiv bzw. kaskadiert angestoßen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Regeln und logische Ausdrücke müssen konfigurierbar auf boolesche Bedingungen abbilden. Ein Verzweigungspfad muss in der Lage sein, entweder externe BSW/RTE-APIs aufzurufen oder weitere Mode Arbitrations zu triggern, um hierarchische oder sequentielle Regelwerke abzubilden. Beide Zweige (<code>True</code> und <code>False</code>) führen prinzipiell identische Klassen von Aktionen (API-Aufrufe bzw. weitere Arbitrierungen) aus.</p>"}, {"id": "FIG-38e5f3a820b59d75", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Ablaufdiagramm in Pseudocode-Notation. Dargestellt ist das Zusammenspiel der RTE und des BswM sowie die funktionale Dekomposition des BswM in die beiden Subkomponenten »Mode Arbitration« und »Mode Control«.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RTE</strong>: Übergeordnete Laufzeitumgebung oberhalb des BswM.\n</li><li><strong>BswM</strong>: Basissoftware-Modul, unterteilt in zwei gestrichelt abgegrenzte Funktionseinheiten:\n<ul class=\"fig-list\"><li><strong>Mode Arbitration</strong>: Einheit zur Regelauswertung mittels boolescher Ausdrücke (<code>Normal_Mode = True &amp; Ifc1_Bus_Off = False</code>).\n</li><li><strong>Mode Control</strong>: Ausführungseinheit für Aktionslisten basierend auf Anweisungen aus der Mode Arbitration.\n</li></ul>\n</li><li><strong>Interne Schnittstelle / Interaktion</strong>: Signalübermittlung (<code>Indicate to Mode Control</code>) von Mode Arbitration an Mode Control zur Anforderung der Ausführung der jeweiligen Aktionsliste (<code>True action list</code> bzw. <code>False action list</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Mode Arbitration wertet eine logische Regelbedingung mit konkreten Zuständen aus (Prüfung auf <code>Normal_Mode = True &amp; Ifc1_Bus_Off = False</code>).\n</li><li>Ergibt die Bedingung <code>True</code>, sendet Mode Arbitration eine Indikation an Mode Control, dass die zu dieser Regel gehörige <code>True action list</code> ausgeführt werden soll.\n</li><li>Ergibt die Bedingung nicht <code>True</code> (<code>Else</code>), sendet Mode Arbitration eine Indikation an Mode Control, dass die zugehörige <code>False action list</code> ausgeführt werden soll.\n</li><li>Mode Control empfängt die Indikation und führt die entsprechende Aktionsliste aus (»Execute action lists based on indications from Mode Arbitration«).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Trennung von Regelauswertung und Aktionsausführung: Die Mode Arbitration evaluiert Bedingungen autonom und delegiert die Ausführung von Aktionslisten ausschließlich per Indikation an die Mode Control. Regeln können aus verknüpften Einzelbedingungen (z. B. Konjunktion mittels <code>&amp;</code>) bestehen. Mode Control setzt die angeforderten Aktionen modular um.</p>"}], "trans": [{"from": "FIG-1a3ff965e48e8b15", "to": "FIG-38e5f3a820b59d75", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Architekturkontext: Ergänzung des übergeordneten Moduls RTE oberhalb des BswM.\n</li><li>Interne BswM-Struktur: Aufteilung des BswM in zwei separate Funktionseinheiten, »Mode Arbitration« und »Mode Control« (gestrichelt umrandet und durch Trennlinie separiert).\n</li><li>Schnittstellen/Zuständigkeiten: Auslagerung der Ausführung von Action Lists aus der Mode Arbitration in die Mode Control; die Mode Arbitration führt Action Lists nicht mehr direkt aus, sondern signalisiert (Indication) die Ausführung der True- bzw. False-Aktionsliste an die Mode Control.\n</li><li>Entscheidungslogik &amp; Syntax: Umstellung der generischen Verzweigung <code>if(condition == true)</code> (Nassi-Shneiderman-Struktur) auf Pseudocode mit konkretem logischen Ausdruck <code>If (Normal_Mode = True &amp; Ifc1_Bus_Off = False)</code> und <code>Else</code>-Zweig.\n</li><li>Aktionsumfang: Wegfall des Verweises auf rekursive Mode Arbitrations („further mode arbitrations“) innerhalb der Aktionslisten.\n</li></ul>"}]};
